(function(){
  var mc = Java.loadClass('net.minecraft.client.Minecraft').getInstance();
  if (mc.player === null) { throw new Error('端点: client 侧无 player（客户端未进入世界）'); }
  var HUD = Java.loadClass('com.merlinkitsune.astral_dice.client.CombatPowerHud');
  var out = {
    hudLoaded: true,
    playerPresent: mc.player !== null,
    defenseOverlayPresent: HUD.DEFENSE_OVERLAY !== null,
    attackOverlayPresent: HUD.ATTACK_OVERLAY !== null,
    defenseFullTex: String(HUD.DEFENSE_FULL),
    defenseEmptyTex: String(HUD.DEFENSE_EMPTY)
  };
  out.overlayIds = [];
  out.overlayProbeErr = '';
  try {
    var Ev = Java.loadClass('com.merlinkitsune.astral_dice.platform.client.event.RegisterGuiOverlaysEvent');
    var Bus = Java.loadClass('com.merlinkitsune.astral_dice.platform.event.LoaderBus');
    var ev = new Ev();
    Bus.INSTANCE.postEvent(ev);
    var entries = ev.getEntries();
    for (var i = 0; i < entries.size(); i++) { out.overlayIds.push(String(entries.get(i).id())); }
  } catch (e) { out.overlayProbeErr = String(e); }
  out.hasDefenseId = out.overlayIds.indexOf('astral_dice:defense_bar') >= 0;
  out.hasAttackId = out.overlayIds.indexOf('astral_dice:attack_bar') >= 0;
  return out;
})()
